In this solution, I have used OleDb to connect and query the Access database. Make sure to add "using System.Data.OleDb;" to your namespaces. Also, you need to add the Microsoft Access Database Engine to your project as a dependency. If you're using Visual Studio, go to Tools > NuGet Package Manager > Manage NuGet Packages for Solution and search for "System.Data.OleDb" and install it in your project.

Assuming you have the necessary components within your form, you can use the following code to achieve the desired functionality:

```csharp
using System;
using System.Data;
using System.Data.OleDb;
using System.Windows.Forms;

namespace WindowsFormsApp
{
    public partial class ApplianceForm : Form
    {
        private OleDbConnection connection;
        private OleDbDataAdapter adapter;
        private DataTable dataTable;

        public ApplianceForm()
        {
            InitializeComponent();
            InitializeDbConnection();
            LoadApplianceTypes();
        }

        private void InitializeDbConnection()
        {
            string connectionString = @"Provider=Microsoft.ACE.OLEDB.12.0;
                                        Data Source=your_database_path_here.mdb";
            connection = new OleDbConnection(connectionString);
            connection.Open();
        }

        private void LoadApplianceTypes()
        {
            string query = "SELECT DISTINCT Appliance FROM Appliances";
            adapter = new OleDbDataAdapter(query, connection);
            DataTable applianceTypes = new DataTable();
            adapter.Fill(applianceTypes);

            comboBoxApplianceTypes.DataSource = applianceTypes;
            comboBoxApplianceTypes.DisplayMember = "Appliance";
        }

        private void comboBoxApplianceTypes_SelectedIndexChanged(object sender, EventArgs e)
        {
            string selectedApplianceType = comboBoxApplianceTypes.Text;

            string query = $"SELECT Appliance, Dimensions, Color, PowerUsage, MonthlyCost FROM Appliances WHERE Appliance = '{selectedApplianceType}'";
            adapter = new OleDbDataAdapter(query, connection);
            dataTable = new DataTable();
            adapter.Fill(dataTable);

            dataGridView1.DataSource = dataTable;
        }

        private void radioButtonSortByEnergy_CheckedChanged(object sender, EventArgs e)
        {
            DataView dataView = dataTable.DefaultView;
            dataView.Sort = "PowerUsage ASC";
            dataTable = dataView.ToTable();
            dataGridView1.DataSource = dataTable;
        }

        private void radioButtonSortByWeeklyCost_CheckedChanged(object sender, EventArgs e)
        {
            DataView dataView = dataTable.DefaultView;
            dataView.Sort = "MonthlyCost ASC";
            dataTable = dataView.ToTable();
            dataGridView1.DataSource = dataTable;
        }

        private void ApplianceForm_FormClosing(object sender, FormClosingEventArgs e)
        {
            if (connection != null)
            {
                connection.Close();
                connection.Dispose();
            }
        }
    }
}
```

