fun ExpensesChart() {
    val paddingValues = 16.dp
    val db = FirebaseFirestore.getInstance()

    // Define your timeframes
    val timeFrames = listOf("Weekly", "Monthly", "Yearly")
    val selectedIndex = remember { mutableStateOf(0) }

    // Fetch and process the expenses data
    val chartEntries = remember { mutableStateOf(entriesOf()) }
    val chartModelProducer = ChartEntryModelProducer(chartEntries.value)

    fun fetchExpensesData(timeFrame: String) {
        // TODO: Customize the query to fetch data according to the selected time frame
        val query = db.collection("expenses")
            .orderBy("timestamp", Query.Direction.ASCENDING)

        query.get().addOnSuccessListener { result ->
            val expenses = mutableListOf<Float>()
            for (document in result) {
                val amount = document.getDouble("amount")?.toFloat() ?: 0f
                expenses.add(amount)
            }
            chartEntries.value = entriesOf(*expenses.toFloatArray())
        }
    }

    Column(modifier = Modifier.padding(paddingValues)) {
        // Timeframe selection buttons
        timeFrames.forEachIndexed { index, timeFrame ->
            Button(
                onClick = {
                    selectedIndex.value = index
                    fetchExpensesData(timeFrame)
                },
                colors = ButtonDefaults.buttonColors(
                    containerColor = if (selectedIndex.value == index) DarkGray else LightGray
                )
            ) {
                Text(timeFrame)
            }
        }

        // Chart
        ProvideChartStyle(chartStyle = m3ChartStyle()) {
            Chart(
                chart = columnChart(),
                chartModelProducer = chartModelProducer,
                startAxis = startAxis(),
                bottomAxis = bottomAxis(),
            )
        }
    }
}

